// Shared application types.
// Import with: import type { User, CreateUserInput } from "@/types"

import type { useTranslations } from "next-intl"
import type { ItemRarity as ItemRarityValue } from "@/lib/src/itemRarities"
import type { ClanInventoryItemDto } from "@/dtos/clanInventoryDTO"
import type { ClanDto } from "@/dtos/clanDTO"
import type { ClanJoinDto } from "@/dtos/clanJoinDTO"
import type { ClanMemberDto, PlayerClanDto } from "@/dtos/clanMemberDTO"
import type { ClanPostDto } from "@/dtos/clanPostDTO"
import type { LfcListingDto, LfpListingDto } from "@/dtos/lfgDTO"
import type { NotificationDto } from "@/dtos/notificationDTO"
import type { PlayerLocationDto } from "@/dtos/playerLocationDTO"
import type { ServerDto } from "@/dtos/serverDTO"
import type { PublicUserDto } from "@/dtos/userDTO"
import type {
  Clan as PrismaClan,
  ClanInventoryItem as PrismaClanInventoryItem,
  ClanJoinMode as PrismaClanJoinMode,
  ClanMember as PrismaClanMember,
  ClanPost as PrismaClanPost,
  ClanRole as PrismaClanRole,
  LfcListing as PrismaLfcListing,
  LfpListing as PrismaLfpListing,
  Notification as PrismaNotification,
  NotificationType as PrismaNotificationType,
  PostVisibility as PrismaPostVisibility,
  Region as PrismaRegion,
  Server as PrismaServer,
  User as PrismaUser,
  UserRole as PrismaUserRole,
  UserServer as PrismaUserServer,
} from "@prisma/client"

// ---------------------------------------------------------------------------
// User
// ---------------------------------------------------------------------------

/** User record as stored in the database (generated by Prisma). */
export type User = PrismaUser

/** Site-wide role: MEMBER (default), MOD or ADMIN. */
export type UserRole = PrismaUserRole

/**
 * Payload for creating a user. `fullname` is derived from name + surname.
 * `password` is the plain password, it is hashed before saving.
 * Steam fields are optional.
 */
export type CreateUserInput = Pick<User, "username" | "name" | "surname" | "email" | "password"> &
  Partial<Pick<User, "steamId" | "steamUsername" | "avatar">>

/** Payload for updating a user. All fields are optional. */
export type UpdateUserInput = Partial<CreateUserInput>

/** One page of the player list (getPlayers). */
export type PlayerList = {
  players: PublicUserDto[]
  // Number of players matching the filters, on all pages.
  total: number
  pageCount: number
}

// ---------------------------------------------------------------------------
// District
// ---------------------------------------------------------------------------

/** Level of a district. */
export type DistrictLevel = 1 | 2 | 3

/** District of the game. */
export type District = {
  name: string
  level: DistrictLevel
}

// ---------------------------------------------------------------------------
// Item
// ---------------------------------------------------------------------------

/** Rarity of an item (lib/src/itemRarities.ts). */
export type ItemRarity = ItemRarityValue

/** ROB RUN item (lib/src/items.ts). */
export type Item = {
  // Last part of the item URL on MetaForge, unique.
  id: string
  name: string
  rarity: ItemRarity | null
  // Kind of item, null for items with a level.
  category: string | null
  level: number | null
  // E.g. "Full" (state at that level), "Mk1" or "owner".
  detail: string | null
  // Sell price in dollars.
  price: number | null
  description: string | null
  // Path in public/items.
  image: string | null
}

// ---------------------------------------------------------------------------
// Clan
// ---------------------------------------------------------------------------

/** Clan record as stored in the database (generated by Prisma). */
export type Clan = PrismaClan

/** ROB RUN server region. */
export type Region = PrismaRegion

/** One page of the clan list (getClans). */
export type ClanList = {
  clans: ClanDto[]
  // Number of clans matching the filters, on all pages.
  total: number
  pageCount: number
}

/** Payload for creating a clan. */
export type CreateClanInput = Pick<Clan, "clanName" | "clanTag" | "clanHref" | "region">

/** Payload for updating a clan. All fields are optional. */
export type UpdateClanInput = Partial<CreateClanInput>

// ---------------------------------------------------------------------------
// Clan member
// ---------------------------------------------------------------------------

/** Rank of a user inside a clan (ROB RUN ranks: LEADER > OFFICER > FIGHTER > RECRUIT). */
export type ClanRole = PrismaClanRole

/** Membership record linking a user to a clan (generated by Prisma). */
export type ClanMember = PrismaClanMember

/** How players join a clan: INVITE, REQUEST or OPEN. */
export type ClanJoinMode = PrismaClanJoinMode

/** Relation of the logged-in user to a clan. */
export type ClanJoinStatus = "NONE" | "REQUESTED" | "INVITED" | "MEMBER"

/** Pending join requests and invites of a clan (getClanJoins). */
export type ClanJoins = {
  requests: ClanJoinDto[]
  invites: ClanJoinDto[]
}

/** One page of the members of a clan (getClanMembers). */
export type ClanMemberList = {
  members: ClanMemberDto[]
  // Number of members matching the filters, on all pages.
  total: number
  pageCount: number
}

/** A clan with its active servers and what the user may do in it (getClan). */
export type ClanDetail = {
  clan: ClanDto
  servers: ServerDto[]
  // True for the leader and officers of the clan.
  canManage: boolean
  // Rank of the logged-in user in the clan, null if not a member.
  viewerRole: ClanRole | null
  joinStatus: ClanJoinStatus
}

/** Numbers and newest entries for the home page (getHomeDashboard). */
export type HomeDashboard = {
  stats: {
    clanCount: number
    playerCount: number
    activeServerCount: number
    lfcCount: number
    lfpCount: number
  }
  clans: ClanDto[]
  // Newest active servers, with their clans and active players counted.
  servers: { server: ServerDto, clanCount: number, playerCount: number }[]
  lfpListings: LfpListingDto[]
}

/** Results of the main menu search bar (search). */
export type SearchResults = {
  clans: ClanDto[]
  players: PublicUserDto[]
}

/** Notification record as stored in the database (generated by Prisma). */
export type Notification = PrismaNotification

/** What a notification is about. Each type has a text in "Notifications.types". */
export type NotificationType = PrismaNotificationType

/** Values in the text of a notification. */
export type NotificationParams = {
  clan?: string
  player?: string
  role?: ClanRole
}

/** One page of /notifications (getNotifications). */
export type NotificationList = {
  notifications: NotificationDto[]
  // Number of notifications on all pages.
  total: number
  pageCount: number
}

/** Listing of a player who searches for a clan (generated by Prisma). */
export type LfcListing = PrismaLfcListing

/** Listing of a clan that searches for players (generated by Prisma). */
export type LfpListing = PrismaLfpListing

/** One page of /lfc (getLfcListings). */
export type LfcList = {
  listings: LfcListingDto[]
  // Number of listings matching the filters, on all pages.
  total: number
  pageCount: number
}

/** One page of /lfp (getLfpListings). */
export type LfpList = {
  listings: LfpListingDto[]
  // Number of listings matching the filters, on all pages.
  total: number
  pageCount: number
}

/** Clan whose LFP listing the logged-in user manages (getMyLfpClans). */
export type ManagedLfpClan = {
  clan: ClanDto
  // Active servers of the clan, the listing can be for them.
  servers: ServerDto[]
  // Current listing, null if there is none.
  listing: { message: string, role: Exclude<ClanRole, "LEADER">, serverIds: string[] } | null
}

/** LFC listing of the logged-in user (getMyLfcListing). */
export type OwnLfcListing = {
  message: string
  region: Region
  // Chosen servers that are still active.
  servers: ServerDto[]
}

/** Servers of a player (getPlayerServers). */
export type PlayerServers = {
  // Their active server, null if there is none.
  server: ServerDto | null
  // Their other servers, last played first.
  history: ServerDto[]
}

/** Server of a player with their location on it (generated by Prisma). */
export type UserServer = PrismaUserServer

/** Location of a player on a server. */
export type PlayerLocation = {
  district: string
  settlement: number
}

/** Servers of the logged-in user (getProfileServers). */
export type ProfileServers = PlayerServers & {
  // Their location on the active server, null without an active server.
  location: PlayerLocationDto | null
}

/** Item of a member in the inventory of a clan (generated by Prisma). */
export type ClanInventoryItem = PrismaClanInventoryItem

/** One page of the inventory of a clan (getClanInventory). */
export type ClanInventoryList = {
  items: ClanInventoryItemDto[]
  // Number of items matching the filters, on all pages.
  total: number
  pageCount: number
  // Active server of the logged-in member, new items are listed there.
  viewerServer: ServerDto | null
}

/** Clan post record as stored in the database (generated by Prisma). */
export type ClanPost = PrismaClanPost

/** Who can see a clan post: PUBLIC (everyone) or MEMBER (members of the clan). */
export type PostVisibility = PrismaPostVisibility

/** One page of the wall of a clan (getClanPosts). */
export type ClanPostList = {
  posts: ClanPostDto[]
  // Number of posts on all pages.
  total: number
  pageCount: number
}

/** A player with their clans and servers (getPlayer). */
export type PlayerDetail = {
  player: PublicUserDto
  clans: PlayerClanDto[]
} & PlayerServers

/** Payload for adding a user to a clan. `role` defaults to RECRUIT. */
export type CreateClanMemberInput = Pick<ClanMember, "userId" | "clanId"> &
  Partial<Pick<ClanMember, "role">>

/** Payload for updating a membership. Only the role can change. */
export type UpdateClanMemberInput = Pick<ClanMember, "role">

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------

/** Game server record as stored in the database (generated by Prisma). */
export type Server = PrismaServer

/** Payload for creating a server. */
export type CreateServerInput = Pick<Server, "serverName" | "beganAt">

/** Payload for updating a server. All fields are optional. */
export type UpdateServerInput = Partial<CreateServerInput>

// ---------------------------------------------------------------------------
// Auth
// ---------------------------------------------------------------------------

/** The logged-in user resolved from an access token. */
export type AccessTokenPayload = {
  userId: string
  username: string
}

// ---------------------------------------------------------------------------
// API
// ---------------------------------------------------------------------------

/**
 * Result of a server action. On failure `error` is a translated message for
 * the whole form and `fieldErrors` holds translated messages per field.
 */
export type ActionResult<T = undefined> =
  | { success: true, data: T }
  | { success: false, error?: string, fieldErrors?: Record<string, string> }

/** Standard response envelope for API routes. */
export type ApiResponse<T> =
  | { success: true, data: T }
  | { success: false, error: string }

// ---------------------------------------------------------------------------
// i18n
// ---------------------------------------------------------------------------

// Makes next-intl type-safe: locales and translation keys are checked at
// compile time against i18n/config.ts and messages/en.json.
declare module "next-intl" {
  interface AppConfig {
    Locale: (typeof import("./i18n/config"))["locales"][number]
    Messages: typeof import("./messages/en.json")
  }
}

/**
 * Translator for the "Validation" namespace. Zod schemas are built by factory
 * functions that take this, so validation messages follow the active language:
 * `useTranslations("Validation")` on the client, `getTranslations("Validation")`
 * on the server.
 */
export type ValidationTranslator = ReturnType<typeof useTranslations<"Validation">>
